def cycle_start(head: "ListNode | None") -> "ListNode | None":
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:                 # they met somewhere inside the cycle
            slow = head
            while slow is not fast:      # same speed now: they meet at the entry
                slow = slow.next
                fast = fast.next
            return slow
    return None                          # fast reached the end: no cycle


